protocol Policy {                                    // Policy
    func decide(_ ctx: SecurityContext, action: Action, resource: Resource) -> Decision
}
struct DocumentService {
    let policy: any Policy
    func read(_ doc: Document, as ctx: SecurityContext) throws -> Document {
        guard case .allow = policy.decide(ctx, action: .read, resource: doc)
        else { throw AccessDenied(reason: "read denied") }   // Guard
        return doc                                            // rule-free
    }
}
